create table cash (
                      id varchar(255) not null,
                      balance numeric(15,2) not null,
                      updated_at timestamp(6) not null,
                      user_id varchar(255) not null,
                      primary key (id)
);
alter table cash add constraint UKdf881k7it0h02bjyi1u5asyeb unique (user_id);
alter table cash add constraint FK1wp8eedfah9xgn0hxump81d6g
    foreign key (user_id) references users;

create table link_codes (
                            id varchar(255) not null,
                            code varchar(6) not null,
                            expires_at timestamp(6) not null,
                            used boolean not null,
                            user_id varchar(255) not null,
                            primary key (id)
);
alter table link_codes add constraint UKk9h0kdipjdda3ph4kkbp4c7mi unique (code);
alter table link_codes add constraint FKgqcy6vxfyi4sbwrafp4wni505
    foreign key (user_id) references users;

create table telegram_links (
                                id varchar(255) not null,
                                chat_id bigint not null,
                                linked_at timestamp(6) not null,
                                user_id varchar(255) not null,
                                primary key (id)
);
alter table telegram_links add constraint UKs6wxqc9f30ax2e1en6lpc4fa8 unique (chat_id);
alter table telegram_links add constraint UKj47o8scau2ve552pa731873o2 unique (user_id);
alter table telegram_links add constraint FKiqa6wke1clubbjtjmuo8jp75d
    foreign key (user_id) references users;
